#!/usr/bin/env node
// Screenshots of the documentation (spec 28, M4): generated by Playwright on
// the demo data, in light and dark theme, regenerated at every release so
// they never go stale. Output: src/assets/screenshots/{light,dark}/<name>.webp
// plus the live-component snapshots in src/data/*.json.
//
// The specs live in e2e/docs/ and run with the Playwright install of e2e/
// (one browser download for the repository) against the real `arenile`
// binary (bin/arenile, built by `make docs-screenshots`) on a temporary
// data dir seeded with `seed demo`. What is captured is listed in
// screenshots.manifest.json. Extra arguments are passed to Playwright, and
// DOCS_ONLY=name1,prefix-* restricts the run.
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const config = join(root, 'e2e', 'docs', 'playwright.config.ts');
const playwright = join(root, 'e2e', 'node_modules', '.bin', 'playwright');

if (!existsSync(playwright)) {
  console.error('docs-screenshots: Playwright not installed, run `make setup` first');
  process.exit(1);
}
const res = spawnSync(playwright, ['test', '-c', config, ...process.argv.slice(2)], {
  cwd: join(root, 'e2e'),
  stdio: 'inherit',
});
process.exit(res.status ?? 1);
